/**
 * agent-loader.ts — Scans agent definition directories and parses AgentDef
 * objects from markdown files with YAML frontmatter.
 *
 * Recognised frontmatter fields:
 *   name        required — unique agent identifier
 *   description optional — one-line summary
 *   tools       optional — comma-separated pi tool names (default: "read,grep,find,ls")
 *   output      optional — default output file path, relative to cwd
 *
 * Search order (first match for a given name wins):
 *   1. <cwd>/agents/
 *   2. <cwd>/.claude/agents/
 *   3. <cwd>/.pi/agents/
 */

import { readdirSync, readFileSync, existsSync } from "fs";
import { resolve, join } from "path";
import type { AgentDef } from "./types.ts";

// ── Constants ─────────────────────────────────────────────────────────────────

const AGENT_DIRS = [
	"agents",
	".claude/agents",
	".pi/agents",
] as const;

const DEFAULT_TOOLS = "read,grep,find,ls";

// ── Frontmatter parser ────────────────────────────────────────────────────────

/**
 * Parses a markdown file with YAML frontmatter.
 * Returns null if the file is missing the frontmatter block or the
 * required "name" field.
 */
export function parseAgentFile(filePath: string): AgentDef | null {
	let raw: string;
	try {
		raw = readFileSync(filePath, "utf-8");
	} catch (err) {
		throw new Error(`Failed to read agent file "${filePath}": ${(err as Error).message}`);
	}

	// Match --- frontmatter --- body
	const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
	if (!match) return null;

	const [, frontmatterBlock, body] = match;

	// Parse simple key: value lines — no multiline or nested YAML support needed
	const frontmatter: Record<string, string> = {};
	for (const line of frontmatterBlock.split(/\r?\n/)) {
		const colonIdx = line.indexOf(":");
		if (colonIdx < 1) continue;
		const key = line.slice(0, colonIdx).trim();
		const value = line.slice(colonIdx + 1).trim();
		if (key) frontmatter[key] = value;
	}

	if (!frontmatter.name) return null;

	return {
		name: frontmatter.name,
		description: frontmatter.description ?? "",
		tools: frontmatter.tools ?? DEFAULT_TOOLS,
		systemPrompt: body.trim(),
		file: filePath,
		outputFile: frontmatter.output ?? undefined,
	};
}

// ── Directory scanner ─────────────────────────────────────────────────────────

/**
 * Scans all agent directories under cwd and returns a deduplicated list of
 * AgentDef objects. First directory wins on name collision.
 *
 * Skips files that fail to parse (logs a warning) but does not throw.
 */
export function scanAgentDirs(cwd: string): AgentDef[] {
	const seen = new Set<string>();
	const agents: AgentDef[] = [];

	for (const rel of AGENT_DIRS) {
		const dir = join(cwd, rel);
		if (!existsSync(dir)) continue;

		let files: string[];
		try {
			files = readdirSync(dir).filter(f => f.endsWith(".md"));
		} catch {
			continue;
		}

		for (const file of files) {
			const fullPath = resolve(dir, file);
			let def: AgentDef | null;
			try {
				def = parseAgentFile(fullPath);
			} catch (err) {
				console.warn(`[agent-loader] Skipping "${fullPath}": ${(err as Error).message}`);
				continue;
			}

			if (!def) {
				console.warn(`[agent-loader] Skipping "${fullPath}": missing frontmatter or name field`);
				continue;
			}

			const key = def.name.toLowerCase();
			if (seen.has(key)) {
				// Earlier directory already claimed this name
				continue;
			}

			seen.add(key);
			agents.push(def);
		}
	}

	return agents;
}

// ── Lookup helpers ────────────────────────────────────────────────────────────

/**
 * Build a name → AgentDef map from a list (case-insensitive keys).
 * Useful for O(1) lookup in the dispatcher.
 */
export function buildAgentIndex(agents: AgentDef[]): Map<string, AgentDef> {
	const index = new Map<string, AgentDef>();
	for (const agent of agents) {
		index.set(agent.name.toLowerCase(), agent);
	}
	return index;
}

/**
 * Look up an agent by name (case-insensitive) from an index.
 * Throws with a helpful message if not found.
 */
export function requireAgent(
	index: Map<string, AgentDef>,
	name: string,
): AgentDef {
	const def = index.get(name.toLowerCase());
	if (!def) {
		const available = [...index.keys()].join(", ");
		throw new Error(
			`Agent "${name}" not found. Available agents: ${available || "(none)"}`
		);
	}
	return def;
}

/**
 * dispatcher.ts — Resolves a DispatchRequest and launches a subagent.
 *
 * Responsibilities:
 *   1. Resolve the AgentDef from the agent index
 *   2. Read input files and prepend their contents to the task string
 *   3. Resolve the output file path (string | true | false → string | null)
 *   4. Resolve session (fresh vs fork → pi --session + optional -c)
 *   5. Create the FIFO and IPC channel
 *   6. Build the pi CLI command string
 *   7. Launch the terminal via terminal.ts
 *   8. Listen on the FIFO, update AgentRun state, write output file on done
 *   9. Return AgentRunResult when the run completes
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { resolve, join, dirname } from "path";
import { randomUUID } from "crypto";
import type {
	DispatchRequest,
	AgentDef,
	AgentRun,
	AgentRunResult,
	IpcMessage,
	TokenUsage,
	ResolvedOutputPath,
} from "./types.ts";
import { createChannel, fifoPath } from "./ipc.ts";
import { launchInTerminal } from "./terminal.ts";
import { resolveSession, recordRun } from "./session.ts";
import { requireAgent, type AgentIndex } from "./agent-loader.ts";

export type AgentIndex = Map<string, AgentDef>;

// ── Output resolution ─────────────────────────────────────────────────────────

function resolveOutputPath(
	request: DispatchRequest,
	def: AgentDef,
): ResolvedOutputPath {
	const { output, cwd, sessionDir } = request;

	if (output === false) return null;

	if (typeof output === "string") {
		// Explicit path — resolve relative to cwd
		return resolve(cwd, output);
	}

	// output === true
	if (def.outputFile) {
		return resolve(cwd, def.outputFile);
	}

	// Fallback: auto-generate inside session dir
	const safe = def.name.toLowerCase().replace(/[^a-z0-9-]/g, "-");
	return join(sessionDir, `${safe}.out.md`);
}

// ── Input file injection ──────────────────────────────────────────────────────

/**
 * Read each input file (relative to cwd) and prepend its contents to the
 * task string. Missing files are warned about but do not throw.
 */
function buildTask(request: DispatchRequest): string {
	const { task, inputs, cwd } = request;

	if (!inputs.length) return task;

	const sections: string[] = [];

	for (const relPath of inputs) {
		const absPath = resolve(cwd, relPath);
		if (!existsSync(absPath)) {
			console.warn(`[dispatcher] Input file not found, skipping: ${absPath}`);
			continue;
		}
		try {
			const content = readFileSync(absPath, "utf-8").trim();
			sections.push(`### Input: ${relPath}\n\n${content}`);
		} catch (err) {
			console.warn(`[dispatcher] Could not read "${absPath}": ${(err as Error).message}`);
		}
	}

	if (!sections.length) return task;

	return `${sections.join("\n\n---\n\n")}\n\n---\n\n${task}`;
}

// ── CLI builder ───────────────────────────────────────────────────────────────

function buildPiCommand(options: {
	model: string;
	tools: string;
	systemPrompt: string;
	piSessionFile: string;
	shouldContinue: boolean;
	fifoPath: string;
	task: string;
	extraArgs: string[];
}): string {
	const {
		model, tools, systemPrompt, piSessionFile,
		shouldContinue, fifoPath, task, extraArgs,
	} = options;

	// Escape single quotes in task and system prompt for shell embedding
	const escapeShell = (s: string) => s.replace(/'/g, `'\\''`);

	const args: string[] = [
		"pi",
		"--mode", "json",
		"-p",
		"--no-extensions",
		"--model", model,
		"--tools", tools,
		"--thinking", "off",
		"--append-system-prompt", `'${escapeShell(systemPrompt)}'`,
		"--session", piSessionFile,
	];

	if (shouldContinue) args.push("-c");
	if (extraArgs.length) args.push(...extraArgs);

	// Inject the FIFO path as an env var so the child wrapper can open it
	// PI_IPC_FIFO is read by openChildChannel() in ipc.ts
	args.push(`'${escapeShell(task)}'`);

	// Wrap in env var injection
	return `PI_IPC_FIFO='${fifoPath}' ${args.join(" ")}`;
}

// ── AgentRun factory ──────────────────────────────────────────────────────────

function makeRun(
	runId: string,
	def: AgentDef,
	request: DispatchRequest,
	resolvedOutputPath: ResolvedOutputPath,
): AgentRun {
	return {
		runId,
		def,
		request,
		resolvedOutputPath,
		status: "queued",
		startedAt: Date.now(),
		output: "",
		lastWork: "",
		toolCount: 0,
		contextPct: 0,
		runCount: 0,
		elapsed: 0,
	};
}

// ── Main dispatch function ────────────────────────────────────────────────────

/**
 * Dispatch a subagent and return a promise that resolves when it completes.
 *
 * @param request   Fully populated DispatchRequest (sessionDir and cwd required)
 * @param agentIndex  Map built by buildAgentIndex() in agent-loader.ts
 * @param onUpdate  Optional callback receiving live AgentRun snapshots
 */
export async function dispatchAgent(
	request: DispatchRequest,
	agentIndex: AgentIndex,
	onUpdate?: (run: AgentRun) => void,
): Promise<AgentRunResult> {
	const { agent, context, terminal, sessionDir, cwd } = request;

	// 1. Resolve agent definition
	const def = requireAgent(agentIndex, agent);

	// 2. Validate terminal *before* touching the filesystem or spawning anything.
	//    launchInTerminal reads PI_TERMINAL here via a dry-run check so we fail
	//    fast with a clear error rather than leaving a dangling FIFO behind.
	if (terminal.type === "env") {
		const app = process.env.PI_TERMINAL?.trim();
		if (!app) {
			throw new Error(
				"PI_TERMINAL environment variable is not set. " +
				"Set it to the name of your terminal binary (e.g. foot, kitty, xterm)."
			);
		}
		// Unknown terminals are handled by the generic launcher — no error here.
	}

	// 3. Resolve output path
	const resolvedOutputPath = resolveOutputPath(request, def);

	// 4. Build the task string with injected input file contents
	const task = buildTask(request);

	// 5. Resolve session (fresh vs fork)
	const { piSessionFile, shouldContinue } = resolveSession(sessionDir, def.name, context);

	// 6. Ensure session dir exists
	if (!existsSync(sessionDir)) mkdirSync(sessionDir, { recursive: true });

	// 7. Create FIFO and IPC channel
	const ipcPath = fifoPath(sessionDir, def.name);
	const transport = { type: "fifo" as const, path: ipcPath, openTimeoutMs: request.ipc.openTimeoutMs };
	const channel = await createChannel(transport);

	// 8. Build pi command
	const model = request.model ?? process.env.PI_MODEL ?? "openrouter/google/gemini-2.5-flash-preview";
	const command = buildPiCommand({
		model,
		tools: def.tools,
		systemPrompt: def.systemPrompt,
		piSessionFile,
		shouldContinue,
		fifoPath: ipcPath,
		task,
		extraArgs: request.extraArgs ?? [],
	});

	// 9. Create run record
	const runId = randomUUID();
	const run = makeRun(runId, def, request, resolvedOutputPath);

	// Elapsed timer
	const elapsedTimer = setInterval(() => {
		run.elapsed = Date.now() - run.startedAt;
		onUpdate?.(snapshot(run));
	}, 1_000);

	// 10. Wire up IPC message handlers
	const textChunks: string[] = [];
	let finalUsage: TokenUsage = { inputTokens: 0, outputTokens: 0 };

	channel.onMessage((msg: IpcMessage) => {
		switch (msg.type) {
			case "text_delta":
				textChunks.push(msg.delta);
				run.output = textChunks.join("");
				run.lastWork = lastNonEmptyLine(run.output);
				break;

			case "tool_start":
				run.toolCount++;
				break;

			case "context_update": {
				const pct = msg.contextWindow > 0
					? (msg.usedTokens / msg.contextWindow) * 100
					: 0;
				run.contextPct = Math.min(100, pct);
				break;
			}

			case "token_usage":
				finalUsage = msg.usage;
				run.usage = msg.usage;
				break;

			case "agent_done":
				// handled in the promise below
				break;

			case "agent_error":
				// handled in the promise below
				break;
		}

		run.status = "running";
		onUpdate?.(snapshot(run));
	});

	// 11. Launch terminal — only reached if all validation above passed
	run.status = "running";
	const launchResult = await launchInTerminal(terminal, {
		command,
		title: `pi — ${def.name}`,
		cwd,
		env: { ...process.env },
	});
	run.pid = launchResult.pid;
	onUpdate?.(snapshot(run));

	// 12. Wait for child to open FIFO, then wait for completion
	return new Promise<AgentRunResult>((resolve, reject) => {
		channel.waitForOpen().catch((err: Error) => {
			clearInterval(elapsedTimer);
			run.status = "failed";
			run.endedAt = Date.now();
			channel.close();
			reject(err);
		});

		channel.onClose(async (err?: Error) => {
			clearInterval(elapsedTimer);
			run.endedAt = Date.now();
			run.elapsed = run.endedAt - run.startedAt;

			// Determine final status from last agent_done / agent_error message
			// (the FIFO close is the signal the child process has exited)
			const lastMsg = [...textChunks]; // already accumulated
			const succeeded = !err && run.status !== "failed";
			run.status = succeeded ? "complete" : "failed";

			// Record session metadata
			try {
				recordRun(sessionDir, def.name, finalUsage);
			} catch {
				// Non-fatal
			}

			// Write output file if configured
			if (resolvedOutputPath && run.output) {
				try {
					const outDir = dirname(resolvedOutputPath);
					if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true });
					writeFileSync(resolvedOutputPath, run.output, "utf-8");
				} catch (writeErr) {
					console.warn(`[dispatcher] Could not write output file "${resolvedOutputPath}": ${(writeErr as Error).message}`);
				}
			}

			onUpdate?.(snapshot(run));

			const result: AgentRunResult = {
				runId,
				agentName: def.name,
				output: run.output,
				exitCode: succeeded ? 0 : 1,
				elapsed: run.elapsed,
				usage: finalUsage,
				outputPath: resolvedOutputPath,
			};

			if (err) {
				reject(err);
			} else {
				resolve(result);
			}
		});
	});
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function lastNonEmptyLine(text: string): string {
	const lines = text.split("\n");
	for (let i = lines.length - 1; i >= 0; i--) {
		if (lines[i].trim()) return lines[i].trim();
	}
	return "";
}

/** Shallow snapshot of AgentRun for onUpdate callbacks (avoids mutation surprises) */
function snapshot(run: AgentRun): AgentRun {
	return { ...run };
}

/**
 * terminal.ts — Terminal launcher for pi subagents.
 *
 * Reads PI_TERMINAL at dispatch time and delegates to the matching launcher.
 * To add a new terminal: implement TerminalLauncher and register it at the
 * bottom of this file with registerLauncher().
 *
 * Each launcher receives a fully-formed command string and a title, and is
 * responsible for spawning the terminal process. It returns the PID of the
 * terminal process (not the pi process inside it).
 *
 * Hidden mode (TerminalTarget { type: "hidden" }) bypasses all of this and
 * pipes stdout/stderr directly to the parent — used for tests and CI.
 */

import { spawn, type ChildProcess } from "child_process";
import type { TerminalTarget, TerminalApp } from "./types.ts";

// ── Launcher interface ────────────────────────────────────────────────────────

export interface LaunchOptions {
	/** The full shell command to run inside the terminal (e.g. "pi --mode json ...") */
	command: string;
	/** Window/tab title shown in the terminal app */
	title: string;
	/** Working directory for the terminal process */
	cwd: string;
	/** Environment variables forwarded to the terminal */
	env: NodeJS.ProcessEnv;
}

export interface LaunchResult {
	/** PID of the terminal process (not the inner pi process) */
	pid: number;
	/** The spawned ChildProcess — only populated in hidden mode */
	process?: ChildProcess;
}

/**
 * A TerminalLauncher knows how to open one specific terminal application.
 * Register new launchers with registerLauncher().
 */
export interface TerminalLauncher {
	/** Must match the PI_TERMINAL value exactly (lowercase) */
	readonly app: TerminalApp;
	/** Human-readable name for error messages */
	readonly displayName: string;
	launch(options: LaunchOptions): Promise<LaunchResult>;
}

// ── Launcher registry ─────────────────────────────────────────────────────────

const launchers = new Map<string, TerminalLauncher>();

export function registerLauncher(launcher: TerminalLauncher): void {
	launchers.set(launcher.app.toLowerCase(), launcher);
}

export function getLauncher(app: string): TerminalLauncher | undefined {
	return launchers.get(app.toLowerCase());
}

// ── Main entry point ──────────────────────────────────────────────────────────

/**
 * Launch a subagent in a terminal window (or pipe it, in hidden mode).
 *
 * Throws if:
 *   - target is { type: "env" } and PI_TERMINAL is not set
 *   - PI_TERMINAL names an unregistered launcher
 */
export async function launchInTerminal(
	target: TerminalTarget,
	options: LaunchOptions,
): Promise<LaunchResult> {
	if (target.type === "hidden") {
		return launchHidden(options);
	}

	// target.type === "env"
	const app = process.env.PI_TERMINAL?.trim();
	if (!app) {
		throw new Error(
			"PI_TERMINAL environment variable is not set. " +
			`Set it to one of: ${[...launchers.keys()].join(", ")}`
		);
	}

	const launcher = getLauncher(app) ?? genericLauncher(app);
	return launcher.launch(options);
}

// ── Hidden launcher (test / CI) ───────────────────────────────────────────────

/**
 * Runs the command as a plain child process with stdio piped to the parent.
 * The LaunchResult.process field is populated so the caller can read stdout.
 */
function launchHidden(options: LaunchOptions): Promise<LaunchResult> {
	return new Promise((resolve, reject) => {
		const proc = spawn("sh", ["-c", options.command], {
			cwd: options.cwd,
			env: options.env,
			stdio: ["ignore", "pipe", "pipe"],
		});

		proc.on("spawn", () => {
			resolve({ pid: proc.pid!, process: proc });
		});

		proc.on("error", reject);
	});
}

// ── Concrete launchers ────────────────────────────────────────────────────────

// ── macOS Terminal.app ──

registerLauncher({
	app: "terminal",
	displayName: "macOS Terminal.app",
	launch({ command, title, cwd, env }): Promise<LaunchResult> {
		// AppleScript: open a new window, set title, run command
		const escaped = command.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
		const script = [
			`tell application "Terminal"`,
			`  activate`,
			`  set w to do script "cd ${cwd} && ${escaped}"`,
			`  set custom title of w to "${title}"`,
			`end tell`,
		].join("\n");

		return new Promise((resolve, reject) => {
			const proc = spawn("osascript", ["-e", script], {
				env,
				stdio: "ignore",
				detached: true,
			});
			proc.unref();
			proc.on("spawn", () => resolve({ pid: proc.pid! }));
			proc.on("error", reject);
		});
	},
});

// ── macOS iTerm2 ──

registerLauncher({
	app: "iterm",
	displayName: "macOS iTerm2",
	launch({ command, title, cwd, env }): Promise<LaunchResult> {
		const escaped = command.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
		const script = [
			`tell application "iTerm"`,
			`  activate`,
			`  set w to (create window with default profile)`,
			`  tell current session of w`,
			`    set name to "${title}"`,
			`    write text "cd ${cwd} && ${escaped}"`,
			`  end tell`,
			`end tell`,
		].join("\n");

		return new Promise((resolve, reject) => {
			const proc = spawn("osascript", ["-e", script], {
				env,
				stdio: "ignore",
				detached: true,
			});
			proc.unref();
			proc.on("spawn", () => resolve({ pid: proc.pid! }));
			proc.on("error", reject);
		});
	},
});

// ── GNOME Terminal (Linux) ──

registerLauncher({
	app: "gnome-terminal",
	displayName: "GNOME Terminal",
	launch({ command, title, cwd, env }): Promise<LaunchResult> {
		return new Promise((resolve, reject) => {
			const proc = spawn(
				"gnome-terminal",
				["--title", title, "--working-directory", cwd, "--", "sh", "-c", command],
				{ env, stdio: "ignore", detached: true },
			);
			proc.unref();
			proc.on("spawn", () => resolve({ pid: proc.pid! }));
			proc.on("error", reject);
		});
	},
});

// ── Windows Terminal (wt) ──

registerLauncher({
	app: "wt",
	displayName: "Windows Terminal",
	launch({ command, title, cwd, env }): Promise<LaunchResult> {
		return new Promise((resolve, reject) => {
			const proc = spawn(
				"wt",
				["--title", title, "--startingDirectory", cwd, "cmd", "/c", command],
				{ env, stdio: "ignore", detached: true, shell: true },
			);
			proc.unref();
			proc.on("spawn", () => resolve({ pid: proc.pid! }));
			proc.on("error", reject);
		});
	},
});

// ── xterm ──

registerLauncher({
	app: "xterm",
	displayName: "xterm",
	launch({ command, title, cwd, env }): Promise<LaunchResult> {
		return new Promise((resolve, reject) => {
			const proc = spawn(
				"xterm",
				["-title", title, "-e", "sh", "-c", command],
				{ cwd, env, stdio: "ignore", detached: true },
			);
			proc.unref();
			proc.on("spawn", () => resolve({ pid: proc.pid! }));
			proc.on("error", reject);
		});
	},
});

// ── foot ──

registerLauncher({
	app: "foot",
	displayName: "foot",
	launch({ command, title, cwd, env }): Promise<LaunchResult> {
		return new Promise((resolve, reject) => {
			const proc = spawn(
				"foot",
				["--title", title, "sh", "-c", command],
				{ cwd, env, stdio: "ignore", detached: true },
			);
			proc.unref();
			proc.on("spawn", () => resolve({ pid: proc.pid! }));
			proc.on("error", reject);
		});
	},
});

// ── Generic fallback ──────────────────────────────────────────────────────────
//
// For any unregistered terminal binary (alacritty, kitty, wezterm, etc.).
// Assumes the binary accepts:  <app> -e sh -c <command>
// which covers the vast majority of Linux terminals.
//
// If your terminal uses a different flag convention, register a specific
// launcher above and it will take precedence.

export function genericLauncher(app: string): TerminalLauncher {
	return {
		app,
		displayName: app,
		launch({ command, cwd, env }): Promise<LaunchResult> {
			return new Promise((resolve, reject) => {
				const proc = spawn(
					app,
					["-e", "sh", "-c", command],
					{ cwd, env, stdio: "ignore", detached: true },
				);
				proc.unref();
				proc.on("spawn", () => resolve({ pid: proc.pid! }));
				proc.on("error", (err) => reject(
					new Error(`Failed to launch terminal "${app}": ${err.message}. ` +
						`If "${app}" uses different flags, register a custom launcher.`)
				));
			});
		},
	};
}

/**
 * types.ts — Core type definitions for the pi multi-agent extension system.
 *
 * Design decisions:
 *   - Terminal   : one per agent, app from PI_TERMINAL env var (throws if unset)
 *   - IPC        : one FIFO per agent, child → parent only, lives in session dir
 *   - AgentGroup : declared in .ts extension files (pi -e my-group.ts)
 *   - Inputs     : file paths read at dispatch time, injected into task string
 *   - Output     : false | true | path string — controls response file writing
 *   - Context    : "fresh" (clean start) | "fork" (resume own prior session)
 *   - Autonomy   : subagents are fully independent after launch; no live parent
 *                  channel. New context = new dispatch.
 */

// ── Token accounting ──────────────────────────────────────────────────────────

export interface TokenUsage {
	inputTokens: number;
	outputTokens: number;
	cacheReadTokens?: number;
	cacheWriteTokens?: number;
}

// ── Agent definition (parsed from .pi/agents/*.md frontmatter) ────────────────

/**
 * Frontmatter fields recognised in agent .md files:
 *
 *   ---
 *   name: code-reviewer
 *   description: Reviews code for bugs and style issues
 *   tools: read,grep,find,ls
 *   output: outputs/code-reviewer.md   # relative to cwd, optional
 *   ---
 *   <system prompt body>
 *
 * outputFile is the default output path used when a dispatch sets output: true
 * and does not supply an explicit path. If neither is present, the dispatcher
 * auto-generates <sessionDir>/<agentName>.out.md.
 */
export interface AgentDef {
	/** Unique identifier, matches filename stem (e.g. "code-reviewer") */
	name: string;
	/** One-line description shown in dashboards and system prompts */
	description: string;
	/** Comma-separated pi tool names this agent is allowed to use */
	tools: string;
	/** Full system prompt body (everything after the frontmatter block) */
	systemPrompt: string;
	/** Absolute path to the source .md file */
	file: string;
	/**
	 * Default output file path, relative to cwd at dispatch time.
	 * Used when a dispatch sets output: true without providing an explicit path.
	 * If absent and output: true, falls back to <sessionDir>/<agentName>.out.md.
	 */
	outputFile?: string;
}

// ── Dispatch context ──────────────────────────────────────────────────────────

/**
 * fresh — agent starts with a clean session (no -c flag passed to pi).
 * fork  — agent resumes its own prior session (-c flag passed).
 *         "Own" means: only this agent's previous runs, never the master's history.
 *         If no prior session exists, behaves like fresh.
 */
export type DispatchContext = "fresh" | "fork";

// ── Output resolution ─────────────────────────────────────────────────────────

/**
 * Controls whether and where the agent's last LLM response is written to disk.
 * The file is overwritten (not appended) after each answer.
 *
 * Resolution order at dispatch time:
 *   1. string  → use this path (relative to cwd)
 *   2. true    → use AgentDef.outputFile if defined,
 *                otherwise auto-generate <sessionDir>/<agentName>.out.md
 *   3. false   → no file written
 */
export type OutputTarget = string | boolean;

// ── Inputs ────────────────────────────────────────────────────────────────────

/**
 * File paths (relative to cwd) read at dispatch time.
 * Their contents are injected into the task string before the agent is launched.
 * This is the only mechanism for passing runtime context into a subagent —
 * there is no live channel after launch.
 *
 * Example: read the last response of another agent and pass it as context:
 *   inputs: ["outputs/refactor-bot.md", "src/auth.ts"]
 */
export type InputFiles = string[];

// ── Terminal target ───────────────────────────────────────────────────────────

/**
 * env    — reads PI_TERMINAL at dispatch time; throws if the variable is unset.
 * hidden — no terminal opened; stdout/stderr piped to parent (for tests / CI).
 *
 * Supported PI_TERMINAL values (add new launchers in terminal.ts):
 *   "terminal"        macOS Terminal.app
 *   "iterm"           macOS iTerm2
 *   "gnome-terminal"  GNOME Terminal (Linux)
 *   "wt"              Windows Terminal
 *   "xterm"           xterm (widely available fallback)
 *   <any string>      forwarded to the launcher registry in terminal.ts
 */
export type TerminalApp =
	| "terminal"
	| "iterm"
	| "gnome-terminal"
	| "wt"
	| "xterm"
	| string;

export type TerminalTarget =
	| { type: "env" }     // normal mode — reads PI_TERMINAL
	| { type: "hidden" }; // test / CI mode — pipes to parent

// ── IPC — FIFO (child → parent only) ─────────────────────────────────────────

/**
 * One FIFO per agent: <sessionDir>/<agentName>.fifo
 *
 * Lifecycle:
 *   1. Parent creates the FIFO (mkfifo) before launching the terminal.
 *   2. Parent opens O_RDONLY|O_NONBLOCK, polls until child connects or
 *      openTimeoutMs elapses (prevents indefinite block on open()).
 *   3. Child opens O_WRONLY, writes newline-delimited JSON (IpcMessage).
 *   4. Parent reads until agent_done / agent_error, then unlinks the FIFO.
 *
 * Kept as a single-variant discriminated union so unix-socket / tcp can be
 * added in ipc.ts without touching any call sites.
 */
export type IpcTransport = FifoTransport;
// future: | UnixSocketTransport | TcpTransport

export interface FifoTransport {
	type: "fifo";
	/** Absolute path: <sessionDir>/<agentName>.fifo — filled in by dispatcher */
	path: string;
	/** Max ms to wait for child to open the write-end. Default: 10_000 */
	openTimeoutMs?: number;
}

// ── IPC message envelope (child → parent, newline-delimited JSON) ─────────────

export type IpcMessage =
	| { type: "text_delta";     runId: string; delta: string }
	| { type: "tool_start";     runId: string; toolName: string }
	| { type: "tool_end";       runId: string; toolName: string; durationMs: number }
	| { type: "context_update"; runId: string; usedTokens: number; contextWindow: number }
	| { type: "token_usage";    runId: string; usage: TokenUsage }
	| { type: "agent_done";     runId: string; exitCode: number; output: string; usage: TokenUsage }
	| { type: "agent_error";    runId: string; message: string };

// ── Dispatch request ──────────────────────────────────────────────────────────

/**
 * Everything needed to launch a single subagent.
 *
 * Example:
 *   {
 *     agent: "worker",
 *     task: "continue this thread",
 *     inputs: ["outputs/planner.md"],
 *     output: "outputs/worker.md",
 *     context: "fork",
 *     terminal: { type: "env" },
 *     ipc: { type: "fifo", path: "" },  // path filled by dispatcher
 *     sessionDir: "/project/.pi/sessions/run-abc123",
 *     cwd: "/project",
 *   }
 */
export interface DispatchRequest {
	/** Agent name, matched case-insensitively against AgentDef.name */
	agent: string;
	/** Base task / prompt. Input file contents are prepended before launch. */
	task: string;
	/**
	 * File paths (relative to cwd) to read and inject into the task at launch.
	 * This is the only way to pass runtime context — there is no live channel.
	 */
	inputs: InputFiles;
	/**
	 * Output file behaviour (see OutputTarget for resolution order).
	 * Defaults to false if omitted.
	 */
	output: OutputTarget;
	/** Session handling */
	context: DispatchContext;
	/** Terminal mode — normally { type: "env" } */
	terminal: TerminalTarget;
	/**
	 * IPC descriptor. The dispatcher sets path = <sessionDir>/<agentName>.fifo
	 * before spawning. Callers can leave path empty.
	 */
	ipc: IpcTransport;
	/** Absolute path to the session directory for this run */
	sessionDir: string;
	/** Working directory for the subprocess */
	cwd: string;
	/** Override the model for this specific dispatch */
	model?: string;
	/** Extra pi CLI flags forwarded verbatim */
	extraArgs?: string[];
}

// ── Resolved output path (computed by dispatcher) ─────────────────────────────

/**
 * After resolving OutputTarget against AgentDef, the dispatcher always works
 * with a concrete optional path.
 */
export type ResolvedOutputPath = string | null;

// ── Live agent run ────────────────────────────────────────────────────────────

export type RunStatus = "queued" | "running" | "complete" | "failed" | "cancelled";

export interface AgentRun {
	runId: string;
	def: AgentDef;
	request: DispatchRequest;
	/** Resolved output path (null if output: false) */
	resolvedOutputPath: ResolvedOutputPath;
	status: RunStatus;
	startedAt: number;
	endedAt?: number;
	/** Full accumulated text output */
	output: string;
	/** Last non-empty line of output (dashboard card preview) */
	lastWork: string;
	toolCount: number;
	/** Context window usage 0–100 % */
	contextPct: number;
	/** How many times this agent has been dispatched in the current session */
	runCount: number;
	/** Elapsed ms, updated every second while running */
	elapsed: number;
	usage?: TokenUsage;
	/** PID of the spawned terminal process */
	pid?: number;
}

// ── Final result ──────────────────────────────────────────────────────────────

/** Resolved value of the Promise returned by dispatchAgent(). */
export interface AgentRunResult {
	runId: string;
	agentName: string;
	output: string;
	exitCode: number;
	elapsed: number;
	usage: TokenUsage;
	/** Path written to, if any */
	outputPath: ResolvedOutputPath;
}

// ── Agent group (exported as default from each .ts extension file) ────────────

/**
 * One group = one extension file = one `pi -e my-group.ts` invocation.
 *
 * Example:
 *
 *   import type { AgentGroup } from "./types.ts";
 *
 *   export default {
 *     name: "backend-team",
 *     description: "Agents for backend development tasks",
 *     members: ["planner", "worker", "reviewer"],
 *     defaults: {
 *       context: "fork",
 *       terminal: { type: "env" },
 *       ipc: { type: "fifo", path: "", openTimeoutMs: 10_000 },
 *       output: true,
 *       inputs: [],
 *     },
 *     overrides: {
 *       "worker": { context: "fresh", output: "outputs/worker-latest.md" },
 *     },
 *   } satisfies AgentGroup;
 */
export interface AgentGroup {
	name: string;
	description?: string;
	/** Must match AgentDef.name values found in .pi/agents/*.md */
	members: string[];
	/** Applied to every dispatch in this group */
	defaults: {
		context: DispatchContext;
		terminal: TerminalTarget;
		/** path is left empty; dispatcher fills it in per run */
		ipc: Pick<FifoTransport, "type" | "openTimeoutMs">;
		output: OutputTarget;
		inputs: InputFiles;
		model?: string;
	};
	/**
	 * Per-agent overrides (key = agent name, case-insensitive).
	 * Wins over defaults for that specific agent.
	 */
	overrides?: Record<string, Partial<{
		context: DispatchContext;
		terminal: TerminalTarget;
		output: OutputTarget;
		inputs: InputFiles;
		model: string;
		tools: string;
		openTimeoutMs: number;
	}>>;
	/** Dashboard grid columns (auto-computed from member count if omitted) */
	gridCols?: number;
}

// ── Session persistence ───────────────────────────────────────────────────────

/**
 * Written to <sessionDir>/sessions/<agentName>.json.
 * Lets the dispatcher know a prior session file exists → pass -c to pi.
 * Each agent tracks only its own session — never the master's.
 */
export interface AgentSession {
	agentName: string;
	/** Absolute path to the pi session .json file */
	sessionFile: string;
	createdAt: number;
	lastUsedAt: number;
	runCount: number;
	totalUsage: TokenUsage;
}

// ── Async / background job types ──────────────────────────────────────────────

export interface AsyncStatus {
	runId: string;
	mode: "single" | "chain";
	state: "queued" | "running" | "complete" | "failed";
	startedAt: number;
	endedAt?: number;
	lastUpdate?: number;
	cwd?: string;
	currentStep?: number;
	steps?: Array<{
		agent: string;
		status: RunStatus;
		durationMs?: number;
		usage?: TokenUsage;
		skills?: string[];
	}>;
	sessionDir?: string;
	outputFile?: string;
	totalTokens?: TokenUsage;
	sessionFile?: string;
}

/** Persisted to disk so the parent can recover state after a restart. */
export interface AsyncJobState {
	asyncId: string;
	asyncDir: string;
	status: "queued" | "running" | "complete" | "failed";
	mode?: "single" | "chain";
	agents?: string[];
	currentStep?: number;
	stepsTotal?: number;
	startedAt?: number;
	updatedAt?: number;
	sessionDir?: string;
	outputFile?: string;
	totalTokens?: TokenUsage;
	sessionFile?: string;
}

/**
 * ipc.ts — IPC channel management for pi subagents.
 *
 * Current transport: FIFO (named pipe), child → parent only.
 * One FIFO per agent, path: <sessionDir>/<agentName>.fifo
 *
 * Extending: implement IpcChannel and register it in createChannel().
 * Callers only ever deal with IpcChannel — the transport is an impl detail.
 *
 * Parent side:
 *   const channel = await createChannel(transport);
 *   channel.onMessage(msg => ...);
 *   await channel.waitForOpen();     // blocks until child connects or timeout
 *   // ... run completes ...
 *   await channel.close();
 *
 * Child side (the pi subprocess wrapper script):
 *   Writes newline-delimited JSON matching IpcMessage to the FIFO path,
 *   which it receives as an env var (PI_IPC_FIFO).
 */

import { open, unlink, constants as fsConstants } from "fs/promises";
import { createReadStream, existsSync } from "fs";
import { execFile } from "child_process";
import { promisify } from "util";
import { createInterface } from "readline";
import type { IpcTransport, IpcMessage, FifoTransport } from "./types.ts";

const execFileAsync = promisify(execFile);

// ── IpcChannel interface ──────────────────────────────────────────────────────

/**
 * The only interface the dispatcher interacts with.
 * Transport-agnostic — add new transports by implementing this.
 */
export interface IpcChannel {
	/** The transport descriptor (for logging / diagnostics) */
	readonly transport: IpcTransport;

	/**
	 * Register a handler called for every IpcMessage received from the child.
	 * May be called multiple times — all handlers are invoked in registration order.
	 */
	onMessage(handler: (msg: IpcMessage) => void): void;

	/**
	 * Register a handler called when the channel is closed (normally or on error).
	 * Receives the error if the close was abnormal.
	 */
	onClose(handler: (err?: Error) => void): void;

	/**
	 * Wait until the child has connected (write-end opened) or the timeout elapses.
	 * Resolves when ready, rejects on timeout.
	 */
	waitForOpen(): Promise<void>;

	/**
	 * Gracefully close the channel and clean up resources (unlink FIFO, etc.).
	 * Safe to call multiple times.
	 */
	close(): Promise<void>;
}

// ── Factory ───────────────────────────────────────────────────────────────────

/**
 * Create and prepare an IpcChannel for the given transport.
 * For FIFO: creates the named pipe on disk. Call waitForOpen() after
 * the terminal process has been spawned.
 */
export async function createChannel(transport: IpcTransport): Promise<IpcChannel> {
	switch (transport.type) {
		case "fifo":
			return createFifoChannel(transport);
		// future:
		// case "unix-socket": return createUnixSocketChannel(transport);
		// case "tcp":         return createTcpChannel(transport);
		default:
			throw new Error(`Unknown IPC transport type: ${(transport as any).type}`);
	}
}

/**
 * Compute the canonical FIFO path for an agent within a session directory.
 * Called by the dispatcher to fill in FifoTransport.path before spawning.
 */
export function fifoPath(sessionDir: string, agentName: string): string {
	const safe = agentName.toLowerCase().replace(/[^a-z0-9-]/g, "-");
	return `${sessionDir}/${safe}.fifo`;
}

// ── FIFO implementation ───────────────────────────────────────────────────────

async function createFifoChannel(transport: FifoTransport): Promise<IpcChannel> {
	const { path, openTimeoutMs = 10_000 } = transport;

	// Create the named pipe (mkfifo). Throws if it already exists or path is bad.
	await execFileAsync("mkfifo", [path]);

	const messageHandlers: Array<(msg: IpcMessage) => void> = [];
	const closeHandlers: Array<(err?: Error) => void> = [];
	let closed = false;

	// ── Open the read end (non-blocking) ──
	//
	// Opening a FIFO O_RDONLY blocks until the write-end is opened.
	// We use O_RDONLY | O_NONBLOCK so open() returns immediately, then we poll
	// via a readline stream. The stream will only emit data once the child opens
	// its write-end — which is fine; readline just waits.
	//
	// Note: On Linux, O_NONBLOCK on a FIFO affects open() but not subsequent
	// reads — readline will still block-read correctly once data arrives.

	let fd: Awaited<ReturnType<typeof open>> | null = null;

	// We open lazily inside waitForOpen so that if createChannel() is called
	// before the FIFO exists on disk (race), the delay is absorbed there.

	let readlineInterface: ReturnType<typeof createInterface> | null = null;
	let openResolve: (() => void) | null = null;
	let openReject: ((err: Error) => void) | null = null;
	let openTimer: ReturnType<typeof setTimeout> | null = null;

	function emitMessage(raw: string): void {
		if (!raw.trim()) return;
		let msg: IpcMessage;
		try {
			msg = JSON.parse(raw) as IpcMessage;
		} catch {
			// Malformed line — skip silently
			return;
		}
		for (const h of messageHandlers) h(msg);
	}

	function emitClose(err?: Error): void {
		if (closed) return;
		closed = true;
		for (const h of closeHandlers) h(err);
	}

	async function startReading(): Promise<void> {
		// Open with O_NONBLOCK to avoid blocking if child hasn't connected yet
		fd = await open(path, fsConstants.O_RDONLY | fsConstants.O_NONBLOCK);

		const stream = createReadStream("", { fd: fd.fd, autoClose: false });
		readlineInterface = createInterface({ input: stream, crlfDelay: Infinity });

		readlineInterface.on("line", (line) => {
			// First line signals the child has connected — resolve waitForOpen
			if (openResolve) {
				if (openTimer) clearTimeout(openTimer);
				const res = openResolve;
				openResolve = null;
				openReject = null;
				res();
			}
			emitMessage(line);
		});

		readlineInterface.on("close", () => {
			emitClose();
		});

		stream.on("error", (err) => {
			emitClose(err);
			if (openReject) {
				if (openTimer) clearTimeout(openTimer);
				const rej = openReject;
				openResolve = null;
				openReject = null;
				rej(err);
			}
		});
	}

	return {
		transport,

		onMessage(handler) {
			messageHandlers.push(handler);
		},

		onClose(handler) {
			closeHandlers.push(handler);
		},

		async waitForOpen(): Promise<void> {
			// Start reading — this opens the fd and sets up readline
			await startReading();

			return new Promise<void>((resolve, reject) => {
				// If readline already fired before we set up the promise
				// (extremely unlikely but possible), resolve immediately.
				if (!openResolve && !closed) {
					resolve();
					return;
				}

				openResolve = resolve;
				openReject = reject;

				openTimer = setTimeout(() => {
					openResolve = null;
					openReject = null;
					reject(new Error(
						`IPC FIFO open timeout after ${openTimeoutMs}ms — ` +
						`child process may have failed to start. Path: ${path}`
					));
				}, openTimeoutMs);
			});
		},

		async close(): Promise<void> {
			if (closed) return;
			closed = true;

			if (openTimer) clearTimeout(openTimer);
			readlineInterface?.close();

			try { await fd?.close(); } catch {}

			// Unlink the FIFO — best effort, ignore if already gone
			try { await unlink(path); } catch {}

			emitClose();
		},
	};
}

// ── Child-side helper ─────────────────────────────────────────────────────────

/**
 * Used by the wrapper script that runs inside the terminal.
 * Opens the FIFO for writing and returns a send function.
 *
 * The wrapper script reads PI_IPC_FIFO from its environment to get the path.
 *
 * Example wrapper usage:
 *   const send = await openChildChannel(process.env.PI_IPC_FIFO!);
 *   send({ type: "text_delta", runId, delta: "..." });
 */
export async function openChildChannel(
	fifoPath: string,
): Promise<(msg: IpcMessage) => void> {
	// O_WRONLY blocks until the read-end is open — the parent opens it first,
	// so this should return almost immediately.
	const fd = await open(fifoPath, fsConstants.O_WRONLY);

	return function send(msg: IpcMessage): void {
		const line = JSON.stringify(msg) + "\n";
		// writeSync keeps messages atomic — no interleaving on a single FIFO
		const buf = Buffer.from(line, "utf-8");
		fd.write(buf).catch(() => {
			// Parent closed the read-end — nothing useful to do
		});
	};
}

/**
 * session.ts — AgentSession persistence.
 *
 * Tracks whether a prior pi session file exists for each agent so the
 * dispatcher knows whether to pass -c (continue) to pi.
 *
 * Session records live at: <sessionDir>/sessions/<agentName>.json
 * Pi session files live at: <sessionDir>/sessions/<agentName>.pi.json
 *
 * The distinction:
 *   *.json      — our AgentSession metadata (runCount, usage totals, etc.)
 *   *.pi.json   — the raw pi session file passed to pi via --session
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { join } from "path";
import type { AgentSession, DispatchContext, TokenUsage } from "./types.ts";

// ── Path helpers ──────────────────────────────────────────────────────────────

export function sessionsDir(sessionDir: string): string {
	return join(sessionDir, "sessions");
}

export function sessionMetaPath(sessionDir: string, agentName: string): string {
	const safe = safeName(agentName);
	return join(sessionsDir(sessionDir), `${safe}.json`);
}

export function piSessionFilePath(sessionDir: string, agentName: string): string {
	const safe = safeName(agentName);
	return join(sessionsDir(sessionDir), `${safe}.pi.json`);
}

function safeName(name: string): string {
	return name.toLowerCase().replace(/[^a-z0-9-]/g, "-");
}

// ── Read / write ──────────────────────────────────────────────────────────────

/**
 * Load an existing AgentSession from disk.
 * Returns null if no session has been recorded yet for this agent.
 */
export function loadSession(
	sessionDir: string,
	agentName: string,
): AgentSession | null {
	const path = sessionMetaPath(sessionDir, agentName);
	if (!existsSync(path)) return null;
	try {
		return JSON.parse(readFileSync(path, "utf-8")) as AgentSession;
	} catch {
		return null;
	}
}

/**
 * Persist an AgentSession to disk.
 * Creates the sessions directory if it doesn't exist.
 */
export function saveSession(sessionDir: string, session: AgentSession): void {
	const dir = sessionsDir(sessionDir);
	if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
	writeFileSync(
		sessionMetaPath(sessionDir, session.agentName),
		JSON.stringify(session, null, 2),
		"utf-8",
	);
}

/**
 * Update an existing session after a run completes, or create a new one.
 * Accumulates token usage across runs.
 */
export function recordRun(
	sessionDir: string,
	agentName: string,
	usage: TokenUsage,
): void {
	const existing = loadSession(sessionDir, agentName);
	const piFile = piSessionFilePath(sessionDir, agentName);
	const now = Date.now();

	if (existing) {
		saveSession(sessionDir, {
			...existing,
			lastUsedAt: now,
			runCount: existing.runCount + 1,
			totalUsage: addUsage(existing.totalUsage, usage),
		});
	} else {
		saveSession(sessionDir, {
			agentName,
			sessionFile: piFile,
			createdAt: now,
			lastUsedAt: now,
			runCount: 1,
			totalUsage: usage,
		});
	}
}

// ── Fresh vs fork resolution ──────────────────────────────────────────────────

export interface SessionResolution {
	/**
	 * Absolute path to the pi session file to pass via --session.
	 * Always set — pi will create it on first run if it doesn't exist.
	 */
	piSessionFile: string;
	/**
	 * Whether to pass -c (continue) to pi.
	 * True only when context is "fork" AND a prior pi session file exists on disk.
	 */
	shouldContinue: boolean;
}

/**
 * Resolve session handling for a dispatch.
 *
 *   fresh → shouldContinue: false (always start clean)
 *   fork  → shouldContinue: true only if the pi session file exists on disk
 *            (if no prior session exists, behaves like fresh silently)
 */
export function resolveSession(
	sessionDir: string,
	agentName: string,
	context: DispatchContext,
): SessionResolution {
	const piSessionFile = piSessionFilePath(sessionDir, agentName);

	if (context === "fresh") {
		return { piSessionFile, shouldContinue: false };
	}

	// fork — only continue if the pi session file actually exists
	const shouldContinue = existsSync(piSessionFile);
	return { piSessionFile, shouldContinue };
}

// ── Utility ───────────────────────────────────────────────────────────────────

function addUsage(a: TokenUsage, b: TokenUsage): TokenUsage {
	return {
		inputTokens: a.inputTokens + b.inputTokens,
		outputTokens: a.outputTokens + b.outputTokens,
		cacheReadTokens: (a.cacheReadTokens ?? 0) + (b.cacheReadTokens ?? 0),
		cacheWriteTokens: (a.cacheWriteTokens ?? 0) + (b.cacheWriteTokens ?? 0),
	};
}

export function applyExtensionDefaults(_url: string, _ctx: any): void {
    // no-op — override if you want custom theme defaults
}

/**
 * riddle-team.ts — Pi multi-agent extension: riddle-maker + riddle-solver.
 *
 * Usage:
 *   PI_TERMINAL=iterm pi -e extensions/groups/riddle-team.ts
 *
 * Each agent runs in its own terminal window. The master shows a compact
 * status panel (name / status / elapsed) but never echoes API replies —
 * those are visible only in each agent's own terminal and written to their
 * output files under outputs/.
 *
 * Commands:
 *   /riddle-make  <topic>   — dispatch riddle-maker with a topic
 *   /riddle-solve           — dispatch riddle-solver, feeding maker's output as input
 *   /riddle-status          — print current status of both agents
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Text, truncateToWidth, visibleWidth } from "@mariozechner/pi-tui";
import { join } from "path";
import { scanAgentDirs, buildAgentIndex } from "../agent-loader.ts";
import { dispatchAgent } from "../dispatcher.ts";
import { applyExtensionDefaults } from "../themeMap.ts";
import type { AgentRun, AgentGroup, DispatchRequest } from "../types.ts";

// ── Group definition ──────────────────────────────────────────────────────────

const GROUP: AgentGroup = {
	name: "riddle-team",
	description: "A maker and a solver walk into a terminal...",
	members: ["riddle-maker", "riddle-solver"],
	defaults: {
		context: "fresh",
		terminal: { type: "env" },       // reads PI_TERMINAL at dispatch time
		ipc: { type: "fifo", path: "", openTimeoutMs: 12_000 },
		output: true,                     // each agent writes to its outputFile
		inputs: [],
	},
	overrides: {
		// solver reads maker's output as input when dispatched via /riddle-solve
		"riddle-solver": { context: "fresh" },
	},
	gridCols: 2,
};

// ── Extension ─────────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
	// Live run state — one entry per agent, keyed by agent name
	const runs = new Map<string, AgentRun>();
	let widgetCtx: any;
	let sessionDir = "";
	let cwd = "";
	let agentIndex: ReturnType<typeof buildAgentIndex>;

	// ── Status widget ─────────────────────────────────────────────────────────
	//
	// Shows name | status | elapsed for each agent.
	// Never displays API output — that stays in each agent's own terminal.

	function updateWidget(): void {
		if (!widgetCtx) return;

		widgetCtx.ui.setWidget("riddle-team", (_tui: any, theme: any) => {
			const text = new Text("", 0, 1);

			return {
				render(width: number): string[] {
					if (runs.size === 0) {
						text.setText(theme.fg("dim", "No agents dispatched yet."));
						return text.render(width);
					}

					const lines: string[] = [];

					for (const run of runs.values()) {
						const statusColor =
							run.status === "idle"     ? "dim"
							: run.status === "running"  ? "accent"
							: run.status === "complete" ? "success"
							: "error";

						const icon =
							run.status === "queued"   ? "○"
							: run.status === "running"  ? "●"
							: run.status === "complete" ? "✓"
							: "✗";

						const elapsedStr = run.elapsed > 0
							? ` ${Math.round(run.elapsed / 1_000)}s`
							: "";

						const name  = theme.fg("accent", run.def.name.padEnd(16));
						const badge = theme.fg(statusColor, `${icon} ${run.status}${elapsedStr}`);

						const row = `  ${name}  ${badge}`;
						lines.push(row);
					}

					text.setText(lines.join("\n"));
					return text.render(width);
				},
				invalidate() { text.invalidate(); },
			};
		});
	}

	// ── Shared dispatch helper ────────────────────────────────────────────────

	async function dispatch(
		agentName: string,
		task: string,
		inputs: string[] = [],
	): Promise<void> {
		const request: DispatchRequest = {
			agent: agentName,
			task,
			inputs,
			output: GROUP.overrides?.[agentName]?.output ?? GROUP.defaults.output,
			context: GROUP.overrides?.[agentName]?.context ?? GROUP.defaults.context,
			terminal: GROUP.defaults.terminal,
			ipc: { type: "fifo", path: "", openTimeoutMs: GROUP.defaults.ipc.openTimeoutMs },
			sessionDir,
			cwd,
		};

		widgetCtx?.ui.notify(`Dispatching ${agentName}…`, "info");

		try {
			// dispatchAgent streams updates via onUpdate — we use them only to
			// refresh the status widget, never to display API content in master.
			await dispatchAgent(request, agentIndex, (run) => {
				runs.set(agentName, run);
				updateWidget();
				// Update status bar
				const alive = [...runs.values()].filter(r => r.status === "running").length;
				widgetCtx?.ui.setStatus(
					"riddle-team",
					alive > 0 ? `${alive} agent(s) running` : "idle",
				);
			});

			widgetCtx?.ui.notify(`${agentName} finished ✓`, "success");
		} catch (err: any) {
			widgetCtx?.ui.notify(`${agentName} failed: ${err?.message ?? err}`, "error");
		}

		updateWidget();
	}

	// ── Commands ──────────────────────────────────────────────────────────────

	pi.registerCommand("riddle-make", {
		description: "Dispatch riddle-maker: /riddle-make <topic>",
		handler: async (args, ctx) => {
			widgetCtx = ctx;
			const topic = args?.trim();
			if (!topic) {
				ctx.ui.notify("Usage: /riddle-make <topic>", "error");
				return;
			}
			// Fire and forget — master does not await or display the output
			dispatch("riddle-maker", `Create a riddle about: ${topic}`).catch(() => {});
		},
	});

	pi.registerCommand("riddle-solve", {
		description: "Dispatch riddle-solver using riddle-maker's last output as input",
		handler: async (args, ctx) => {
			widgetCtx = ctx;

			const makerRun = runs.get("riddle-maker");
			if (!makerRun || makerRun.status !== "complete") {
				ctx.ui.notify(
					"riddle-maker has not completed yet. Run /riddle-make <topic> first.",
					"warning",
				);
				return;
			}

			// Pass maker's output file as input so solver reads it at launch time
			const makerOutputFile = makerRun.resolvedOutputPath
				?? join(cwd, "outputs/riddle-maker.md");

			const extraTask = args?.trim()
				? `Additional instruction: ${args.trim()}`
				: "";

			dispatch(
				"riddle-solver",
				["Solve the riddle in the input file.", extraTask].filter(Boolean).join("\n"),
				[makerOutputFile],
			).catch(() => {});
		},
	});

	pi.registerCommand("riddle-status", {
		description: "Print current status of both agents",
		handler: async (_args, ctx) => {
			widgetCtx = ctx;
			if (runs.size === 0) {
				ctx.ui.notify("No agents dispatched yet.", "info");
				return;
			}

			const lines = [...runs.values()].map(r => {
				const elapsed = r.elapsed > 0 ? ` (${Math.round(r.elapsed / 1_000)}s)` : "";
				return `${r.def.name}: ${r.status}${elapsed}`;
			});

			ctx.ui.notify(lines.join("\n"), "info");
		},
	});

	// ── Session start ─────────────────────────────────────────────────────────

	pi.on("session_start", async (_event, ctx) => {
		applyExtensionDefaults(import.meta.url, ctx);
		widgetCtx = ctx;
		cwd = ctx.cwd;
		sessionDir = join(cwd, ".pi", "sessions", "riddle-team");

		// Load agent definitions
		const defs = scanAgentDirs(cwd);
		agentIndex = buildAgentIndex(defs);

		// Validate that both expected agents are present
		const missing = GROUP.members.filter(m => !agentIndex.has(m.toLowerCase()));
		if (missing.length) {
			ctx.ui.notify(
				`Warning: missing agent definitions: ${missing.join(", ")}\n` +
				`Add them to .pi/agents/`,
				"warning",
			);
		}

		// Master has no tools — it only dispatches via commands
		pi.setActiveTools([]);

		ctx.ui.setStatus("riddle-team", "idle");
		ctx.ui.notify(
			`riddle-team ready\n\n` +
			`/riddle-make <topic>   — generate a riddle\n` +
			`/riddle-solve          — solve the last riddle\n` +
			`/riddle-status         — check agent status`,
			"info",
		);

		updateWidget();
	});
}

