function buildPiCommand(options: {
	model: string;
	tools: string;
	systemPrompt: string;
	piSessionFile: string;
	shouldContinue: boolean;
	fifoPath: string;
	task: string;
	extraArgs: string[];
}): string {
	const {
		model, tools, systemPrompt, piSessionFile,
		shouldContinue, fifoPath, task, extraArgs,
	} = options;

	// Escape single quotes in task and system prompt for shell embedding
	const escapeShell = (s: string) => s.replace(/'/g, `'\\''`);

	const args: string[] = [
		"pi",
		"--mode", "json",
		"-p",
		"--no-extensions",
		"--model", model,
		"--tools", tools,
		"--thinking", "off",
		"--append-system-prompt", `'${escapeShell(systemPrompt)}'`,
		"--session", piSessionFile,
	];

	if (shouldContinue) args.push("-c");
	if (extraArgs.length) args.push(...extraArgs);

	// Inject the FIFO path as an env var so the child wrapper can open it
	// PI_IPC_FIFO is read by openChildChannel() in ipc.ts
	args.push(`'${escapeShell(task)}'`);

	// Wrap in env var injection
	return `PI_IPC_FIFO='${fifoPath}' ${args.join(" ")}`;
}

edits.newText:
function buildPiCommand(options: {
	runId: string;
	model: string;
	tools: string;
	systemPrompt: string;
	piSessionFile: string;
	shouldContinue: boolean;
	fifoPath: string;
	task: string;
	extraArgs: string[];
	cwd: string;
}): string {
	const {
		runId,
		model, tools, systemPrompt, piSessionFile,
		shouldContinue, fifoPath, task, extraArgs, cwd,
	} = options;

	const payload = {
		runId,
		fifoPath,
		cwd,
		piArgs: [
			"--mode", "json",
			"-p",
			"--no-extensions",
			"--model", model,
			"--tools", tools,
			"--thinking", "off",
			"--append-system-prompt", systemPrompt,
			"--session", piSessionFile,
			...(shouldContinue ? ["-c"] : []),
			...extraArgs,
			task,
		],
	};

	const encoded = Buffer.from(JSON.stringify(payload), "utf-8").toString("base64");
	const wrapperPath = resolve(import.meta.dirname ?? process.cwd(), "child-runner.js");
	const escapeShell = (s: string) => s.replace(/'/g, `'\\''`);

	return `node '${escapeShell(wrapperPath)}' '${escapeShell(encoded)}'`;
}

