/**
 * dispatcher.ts — Resolves a DispatchRequest and launches a subagent.
 *
 * Responsibilities:
 *   1. Resolve the AgentDef from the agent index
 *   2. Read input files and prepend their contents to the task string
 *   3. Resolve the output file path (string | true | false → string | null)
 *   4. Resolve session (fresh vs fork → pi --session + optional -c)
 *   5. Create the FIFO and IPC channel
 *   6. Build the pi CLI command string
 *   7. Launch the terminal via terminal.ts
 *   8. Listen on the FIFO, update AgentRun state, write output file on done
 *   9. Return AgentRunResult when the run completes
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { resolve, join, dirname } from "path";
import { randomUUID } from "crypto";
import type {
	DispatchRequest,
	AgentDef,
	AgentRun,
	AgentRunResult,
	IpcMessage,
	TokenUsage,
	ResolvedOutputPath,
} from "./types.ts";
import { createChannel, fifoPath } from "./ipc.ts";
import { launchInTerminal } from "./terminal.ts";
import { resolveSession, recordRun } from "./session.ts";
import { requireAgent } from "./agent-loader.ts";

export type AgentIndex = Map<string, AgentDef>;

// ── Output resolution ─────────────────────────────────────────────────────────

function resolveOutputPath(
	request: DispatchRequest,
	def: AgentDef,
): ResolvedOutputPath {
	const { output, cwd, sessionDir } = request;

	if (output === false) return null;

	if (typeof output === "string") {
		// Explicit path — resolve relative to cwd
		return resolve(cwd, output);
	}

	// output === true
	if (def.outputFile) {
		return resolve(cwd, def.outputFile);
	}

	// Fallback: auto-generate inside session dir
	const safe = def.name.toLowerCase().replace(/[^a-z0-9-]/g, "-");
	return join(sessionDir, `${safe}.out.md`);
}

// ── Input file injection ──────────────────────────────────────────────────────

/**
 * Read each input file (relative to cwd) and prepend its contents to the
 * task string. Missing files are warned about but do not throw.
 */
function buildTask(request: DispatchRequest): string {
	const { task, inputs, cwd } = request;

	if (!inputs.length) return task;

	const sections: string[] = [];

	for (const relPath of inputs) {
		const absPath = resolve(cwd, relPath);
		if (!existsSync(absPath)) {
			console.warn(`[dispatcher] Input file not found, skipping: ${absPath}`);
			continue;
		}
		try {
			const content = readFileSync(absPath, "utf-8").trim();
			sections.push(`### Input: ${relPath}\n\n${content}`);
		} catch (err) {
			console.warn(`[dispatcher] Could not read "${absPath}": ${(err as Error).message}`);
		}
	}

	if (!sections.length) return task;

	return `${sections.join("\n\n---\n\n")}\n\n---\n\n${task}`;
}

// ── CLI builder ───────────────────────────────────────────────────────────────

function buildPiCommand(options: {
	runId: string;
	model: string;
	tools: string;
	systemPrompt: string;
	piSessionFile: string;
	shouldContinue: boolean;
	fifoPath: string;
	task: string;
	extraArgs: string[];
	cwd: string;
}): string {
	const {
		runId,
		model, tools, systemPrompt, piSessionFile,
		shouldContinue, fifoPath, task, extraArgs, cwd,
	} = options;

	const payload = {
		runId,
		fifoPath,
		cwd,
		piArgs: [
			"--mode", "json",
			"-p",
			"--no-extensions",
			"--model", model,
			"--tools", tools,
			"--thinking", "off",
			"--append-system-prompt", systemPrompt,
			"--session", piSessionFile,
			...(shouldContinue ? ["-c"] : []),
			...extraArgs,
			task,
		],
	};

	const encoded = Buffer.from(JSON.stringify(payload), "utf-8").toString("base64");
	const wrapperPath = resolve(process.cwd(), "child-runner.js");
	const escapeShell = (s: string) => s.replace(/'/g, `'\\''`);

	return `node '${escapeShell(wrapperPath)}' '${escapeShell(encoded)}'`;
}

// ── AgentRun factory ──────────────────────────────────────────────────────────

function makeRun(
	runId: string,
	def: AgentDef,
	request: DispatchRequest,
	resolvedOutputPath: ResolvedOutputPath,
): AgentRun {
	return {
		runId,
		def,
		request,
		resolvedOutputPath,
		status: "queued",
		startedAt: Date.now(),
		output: "",
		lastWork: "",
		toolCount: 0,
		contextPct: 0,
		runCount: 0,
		elapsed: 0,
	};
}

// ── Main dispatch function ────────────────────────────────────────────────────

/**
 * Dispatch a subagent and return a promise that resolves when it completes.
 *
 * @param request   Fully populated DispatchRequest (sessionDir and cwd required)
 * @param agentIndex  Map built by buildAgentIndex() in agent-loader.ts
 * @param onUpdate  Optional callback receiving live AgentRun snapshots
 */
export async function dispatchAgent(
	request: DispatchRequest,
	agentIndex: AgentIndex,
	onUpdate?: (run: AgentRun) => void,
): Promise<AgentRunResult> {
	const { agent, context, terminal, sessionDir, cwd } = request;

	// 1. Resolve agent definition
	const def = requireAgent(agentIndex, agent);

	// 2. Validate terminal *before* touching the filesystem or spawning anything.
	//    launchInTerminal reads PI_TERMINAL here via a dry-run check so we fail
	//    fast with a clear error rather than leaving a dangling FIFO behind.
	if (terminal.type === "env") {
		const app = process.env.PI_TERMINAL?.trim();
		if (!app) {
			throw new Error(
				"PI_TERMINAL environment variable is not set. " +
				"Set it to the name of your terminal binary (e.g. foot, kitty, xterm)."
			);
		}
		// Unknown terminals are handled by the generic launcher — no error here.
	}

	// 3. Resolve output path
	const resolvedOutputPath = resolveOutputPath(request, def);

	// 4. Build the task string with injected input file contents
	const task = buildTask(request);

	// 5. Resolve session (fresh vs fork)
	const { piSessionFile, shouldContinue } = resolveSession(sessionDir, def.name, context);

	// 6. Ensure session dir exists
	if (!existsSync(sessionDir)) mkdirSync(sessionDir, { recursive: true });

	// 7. Create FIFO and IPC channel
	const ipcPath = fifoPath(sessionDir, def.name);
	const transport = { type: "fifo" as const, path: ipcPath, openTimeoutMs: request.ipc.openTimeoutMs };
	const channel = await createChannel(transport);

	// 8. Create run record
	const runId = randomUUID();
	const run = makeRun(runId, def, request, resolvedOutputPath);

	// 9. Build pi command
	const model = request.model ?? process.env.PI_MODEL ?? "openrouter/google/gemini-2.5-flash-preview";
	const command = buildPiCommand({
		runId,
		model,
		tools: def.tools,
		systemPrompt: def.systemPrompt,
		piSessionFile,
		shouldContinue,
		fifoPath: ipcPath,
		task,
		extraArgs: request.extraArgs ?? [],
		cwd,
	});

	// Elapsed timer
	const elapsedTimer = setInterval(() => {
		run.elapsed = Date.now() - run.startedAt;
		onUpdate?.(snapshot(run));
	}, 1_000);

	// 10. Wire up IPC message handlers
	const textChunks: string[] = [];
	let finalUsage: TokenUsage = { inputTokens: 0, outputTokens: 0 };
	let sawDone = false;
	let doneExitCode = 1;
	let terminalErr: string | undefined;

	channel.onMessage((msg: IpcMessage) => {
		switch (msg.type) {
			case "text_delta":
				textChunks.push(msg.delta);
				run.output = textChunks.join("");
				run.lastWork = lastNonEmptyLine(run.output);
				break;

			case "tool_start":
				run.toolCount++;
				break;

			case "context_update": {
				const pct = msg.contextWindow > 0
					? (msg.usedTokens / msg.contextWindow) * 100
					: 0;
				run.contextPct = Math.min(100, pct);
				break;
			}

			case "token_usage":
				finalUsage = msg.usage;
				run.usage = msg.usage;
				break;

			case "agent_done":
				sawDone = true;
				doneExitCode = msg.exitCode;
				finalUsage = msg.usage;
				run.usage = msg.usage;
				if (msg.output) {
					run.output = msg.output;
					run.lastWork = lastNonEmptyLine(run.output);
				}
				break;

			case "agent_error":
				terminalErr = msg.message;
				run.status = "failed";
				break;
		}

		if (run.status !== "failed") run.status = "running";
		onUpdate?.(snapshot(run));
	});

	// 11. Launch terminal — only reached if all validation above passed
	run.status = "running";
	const launchResult = await launchInTerminal(terminal, {
		command,
		title: `pi — ${def.name}`,
		cwd,
		env: { ...process.env },
	});
	run.pid = launchResult.pid;
	onUpdate?.(snapshot(run));

	// 12. Wait for child to open FIFO, then wait for completion
	return new Promise<AgentRunResult>((resolve, reject) => {
		channel.waitForOpen().catch((err: Error) => {
			clearInterval(elapsedTimer);
			run.status = "failed";
			run.endedAt = Date.now();
			channel.close();
			reject(err);
		});

		channel.onClose(async (err?: Error) => {
			clearInterval(elapsedTimer);
			run.endedAt = Date.now();
			run.elapsed = run.endedAt - run.startedAt;

			const succeeded = !err && !terminalErr && sawDone && doneExitCode === 0;
			run.status = succeeded ? "complete" : "failed";

			// Record session metadata
			try {
				recordRun(sessionDir, def.name, finalUsage);
			} catch {
				// Non-fatal
			}

			// Write output file if configured
			if (resolvedOutputPath && run.output) {
				try {
					const outDir = dirname(resolvedOutputPath);
					if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true });
					writeFileSync(resolvedOutputPath, run.output, "utf-8");
				} catch (writeErr) {
					console.warn(`[dispatcher] Could not write output file "${resolvedOutputPath}": ${(writeErr as Error).message}`);
				}
			}

			onUpdate?.(snapshot(run));

			const result: AgentRunResult = {
				runId,
				agentName: def.name,
				output: run.output,
				exitCode: succeeded ? 0 : 1,
				elapsed: run.elapsed,
				usage: finalUsage,
				outputPath: resolvedOutputPath,
			};

			if (err) {
				reject(new Error(terminalErr ? `${terminalErr} (${err.message})` : err.message));
			} else if (terminalErr) {
				reject(new Error(terminalErr));
			} else if (!succeeded) {
				reject(new Error(`Agent "${def.name}" did not complete successfully`));
			} else {
				resolve(result);
			}
		});
	});
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function lastNonEmptyLine(text: string): string {
	const lines = text.split("\n");
	for (let i = lines.length - 1; i >= 0; i--) {
		if (lines[i].trim()) return lines[i].trim();
	}
	return "";
}

/** Shallow snapshot of AgentRun for onUpdate callbacks (avoids mutation surprises) */
function snapshot(run: AgentRun): AgentRun {
	return { ...run };
}

/**
 * ipc.ts — IPC channel management for pi subagents.
 *
 * Current transport: FIFO (named pipe), child → parent only.
 * One FIFO per agent, path: <sessionDir>/<agentName>.fifo
 *
 * Extending: implement IpcChannel and register it in createChannel().
 * Callers only ever deal with IpcChannel — the transport is an impl detail.
 *
 * Parent side:
 *   const channel = await createChannel(transport);
 *   channel.onMessage(msg => ...);
 *   await channel.waitForOpen();     // blocks until child connects or timeout
 *   // ... run completes ...
 *   await channel.close();
 *
 * Child side (the pi subprocess wrapper script):
 *   Writes newline-delimited JSON matching IpcMessage to the FIFO path,
 *   which it receives as an env var (PI_IPC_FIFO).
 */

import { open, unlink, constants as fsConstants } from "fs/promises";
import { createReadStream } from "fs";
import { execFile } from "child_process";
import { promisify } from "util";
import { createInterface } from "readline";
import type { IpcTransport, IpcMessage, FifoTransport } from "./types.ts";

const execFileAsync = promisify(execFile);

// ── IpcChannel interface ──────────────────────────────────────────────────────

/**
 * The only interface the dispatcher interacts with.
 * Transport-agnostic — add new transports by implementing this.
 */
export interface IpcChannel {
	/** The transport descriptor (for logging / diagnostics) */
	readonly transport: IpcTransport;

	/**
	 * Register a handler called for every IpcMessage received from the child.
	 * May be called multiple times — all handlers are invoked in registration order.
	 */
	onMessage(handler: (msg: IpcMessage) => void): void;

	/**
	 * Register a handler called when the channel is closed (normally or on error).
	 * Receives the error if the close was abnormal.
	 */
	onClose(handler: (err?: Error) => void): void;

	/**
	 * Wait until the child has connected (write-end opened) or the timeout elapses.
	 * Resolves when ready, rejects on timeout.
	 */
	waitForOpen(): Promise<void>;

	/**
	 * Gracefully close the channel and clean up resources (unlink FIFO, etc.).
	 * Safe to call multiple times.
	 */
	close(): Promise<void>;
}

// ── Factory ───────────────────────────────────────────────────────────────────

/**
 * Create and prepare an IpcChannel for the given transport.
 * For FIFO: creates the named pipe on disk. Call waitForOpen() after
 * the terminal process has been spawned.
 */
export async function createChannel(transport: IpcTransport): Promise<IpcChannel> {
	switch (transport.type) {
		case "fifo":
			return createFifoChannel(transport);
		// future:
		// case "unix-socket": return createUnixSocketChannel(transport);
		// case "tcp":         return createTcpChannel(transport);
		default:
			throw new Error(`Unknown IPC transport type: ${(transport as any).type}`);
	}
}

/**
 * Compute the canonical FIFO path for an agent within a session directory.
 * Called by the dispatcher to fill in FifoTransport.path before spawning.
 */
export function fifoPath(sessionDir: string, agentName: string): string {
	const safe = agentName.toLowerCase().replace(/[^a-z0-9-]/g, "-");
	return `${sessionDir}/${safe}.fifo`;
}

// ── FIFO implementation ───────────────────────────────────────────────────────

async function createFifoChannel(transport: FifoTransport): Promise<IpcChannel> {
	const { path, openTimeoutMs = 10_000 } = transport;

	// Create the named pipe (mkfifo). Throws if it already exists or path is bad.
	await execFileAsync("mkfifo", [path]);

	const messageHandlers: Array<(msg: IpcMessage) => void> = [];
	const closeHandlers: Array<(err?: Error) => void> = [];

	let fd: Awaited<ReturnType<typeof open>> | null = null;
	let readlineInterface: ReturnType<typeof createInterface> | null = null;
	let startPromise: Promise<void> | null = null;
	let openResolve: (() => void) | null = null;
	let openReject: ((err: Error) => void) | null = null;
	let openTimer: ReturnType<typeof setTimeout> | null = null;
	let opened = false;
	let cleanedUp = false;
	let closeEmitted = false;

	function resolveOpenIfPending(): void {
		if (!openResolve) return;
		if (openTimer) clearTimeout(openTimer);
		const res = openResolve;
		openResolve = null;
		openReject = null;
		res();
	}

	function rejectOpenIfPending(err: Error): void {
		if (!openReject) return;
		if (openTimer) clearTimeout(openTimer);
		const rej = openReject;
		openResolve = null;
		openReject = null;
		rej(err);
	}

	function emitMessage(raw: string): void {
		if (!raw.trim()) return;
		let msg: IpcMessage;
		try {
			msg = JSON.parse(raw) as IpcMessage;
		} catch {
			return;
		}
		if (!opened) {
			opened = true;
			resolveOpenIfPending();
		}
		for (const h of messageHandlers) h(msg);
	}

	function emitClose(err?: Error): void {
		if (closeEmitted) return;
		closeEmitted = true;
		for (const h of closeHandlers) h(err);
	}

	async function cleanup(): Promise<void> {
		if (cleanedUp) return;
		cleanedUp = true;

		if (openTimer) clearTimeout(openTimer);
		try { readlineInterface?.close(); } catch {}
		try { await fd?.close(); } catch {}
		try { await unlink(path); } catch {}
	}

	async function startReading(): Promise<void> {
		if (startPromise) return startPromise;

		startPromise = (async () => {
			fd = await open(path, fsConstants.O_RDONLY | fsConstants.O_NONBLOCK);
			const stream = createReadStream("", { fd: fd.fd, autoClose: false });
			readlineInterface = createInterface({ input: stream, crlfDelay: Infinity });

			readlineInterface.on("line", emitMessage);

			readlineInterface.on("close", () => {
				cleanup()
					.then(() => emitClose())
					.catch((err) => emitClose(err as Error));
			});

			stream.on("error", (err) => {
				rejectOpenIfPending(err as Error);
				cleanup()
					.then(() => emitClose(err as Error))
					.catch((cleanupErr) => emitClose(cleanupErr as Error));
			});
		})();

		return startPromise;
	}

	return {
		transport,

		onMessage(handler) {
			messageHandlers.push(handler);
		},

		onClose(handler) {
			closeHandlers.push(handler);
		},

		async waitForOpen(): Promise<void> {
			await startReading();
			if (opened) return;

			return new Promise<void>((resolve, reject) => {
				openResolve = resolve;
				openReject = reject;
				openTimer = setTimeout(() => {
					const timeoutErr = new Error(
						`IPC FIFO open timeout after ${openTimeoutMs}ms — ` +
						`child process may have failed to start. Path: ${path}`
					);
					rejectOpenIfPending(timeoutErr);
				}, openTimeoutMs);
			});
		},

		async close(): Promise<void> {
			await cleanup();
			emitClose();
		},
	};
}

// ── Child-side helper ─────────────────────────────────────────────────────────

/**
 * Used by the wrapper script that runs inside the terminal.
 * Opens the FIFO for writing and returns a send function.
 *
 * The wrapper script reads PI_IPC_FIFO from its environment to get the path.
 *
 * Example wrapper usage:
 *   const send = await openChildChannel(process.env.PI_IPC_FIFO!);
 *   send({ type: "text_delta", runId, delta: "..." });
 */
export async function openChildChannel(
	fifoPath: string,
): Promise<(msg: IpcMessage) => void> {
	// O_WRONLY blocks until the read-end is open — the parent opens it first,
	// so this should return almost immediately.
	const fd = await open(fifoPath, fsConstants.O_WRONLY);

	return function send(msg: IpcMessage): void {
		const line = JSON.stringify(msg) + "\n";
		// writeSync keeps messages atomic — no interleaving on a single FIFO
		const buf = Buffer.from(line, "utf-8");
		fd.write(buf).catch(() => {
			// Parent closed the read-end — nothing useful to do
		});
	};
}

